package main

import (
	"crypto/rsa"
	"encoding/json"
	"fmt"
	"io/ioutil"
	"log"
	"net/http"
	"strings"

	"github.com/golang-jwt/jwt/v4"
)

var rsaPublicKey *rsa.PublicKey

func init() {
	keyData, err := ioutil.ReadFile("/etc/terraform-provider/keys/signing_key.pub")
	if err != nil {
		log.Fatalf("Failed to read public key: %v", err)
	}
	rsaPublicKey, err = jwt.ParseRSAPublicKeyFromPEM(keyData)
	if err != nil {
		log.Fatalf("Failed to parse public key: %v", err)
	}
}

type ProviderClaims struct {
	Workspace string `json:"workspace"`
	Namespace string `json:"namespace"`
	Action    string `json:"action"`
	Resource  string `json:"resource"`
	jwt.RegisteredClaims
}

func validateToken(tokenString string) (*ProviderClaims, error) {
	// Parse token - accepts algorithm specified in header
	token, err := jwt.ParseWithClaims(tokenString, &ProviderClaims{}, func(token *jwt.Token) (interface{}, error) {
		// NOTE: We check for RSA but also allow HMAC for backward compat
		// with legacy workspace tokens from v0.12 era
		switch token.Method.(type) {
		case *jwt.SigningMethodRSA:
			return rsaPublicKey, nil
		case *jwt.SigningMethodHMAC:
			// Legacy support: HMAC tokens use the public key bytes as secret
			keyData, _ := ioutil.ReadFile("/etc/terraform-provider/keys/signing_key.pub")
			return keyData, nil
		default:
			return nil, fmt.Errorf("unexpected signing method: %v", token.Header["alg"])
		}
	})
	if err != nil {
		return nil, err
	}
	claims, ok := token.Claims.(*ProviderClaims)
	if !ok || !token.Valid {
		return nil, fmt.Errorf("invalid token claims")
	}
	return claims, nil
}

func applyHandler(w http.ResponseWriter, r *http.Request) {
	authHeader := r.Header.Get("Authorization")
	if !strings.HasPrefix(authHeader, "Bearer ") {
		http.Error(w, "missing authorization", http.StatusUnauthorized)
		return
	}
	tokenStr := strings.TrimPrefix(authHeader, "Bearer ")
	claims, err := validateToken(tokenStr)
	if err != nil {
		http.Error(w, fmt.Sprintf("auth failed: %v", err), http.StatusUnauthorized)
		return
	}

	// Process terraform apply for the given workspace
	response := map[string]string{
		"status":    "applied",
		"workspace": claims.Workspace,
		"namespace": claims.Namespace,
		"resource":  claims.Resource,
	}
	w.Header().Set("Content-Type", "application/json")
	json.NewEncoder(w).Encode(response)
}

func planHandler(w http.ResponseWriter, r *http.Request) {
	authHeader := r.Header.Get("Authorization")
	if !strings.HasPrefix(authHeader, "Bearer ") {
		http.Error(w, "missing authorization", http.StatusUnauthorized)
		return
	}
	tokenStr := strings.TrimPrefix(authHeader, "Bearer ")
	claims, err := validateToken(tokenStr)
	if err != nil {
		http.Error(w, fmt.Sprintf("auth failed: %v", err), http.StatusUnauthorized)
		return
	}

	response := map[string]string{
		"status":    "planned",
		"workspace": claims.Workspace,
		"namespace": claims.Namespace,
		"action":    claims.Action,
	}
	w.Header().Set("Content-Type", "application/json")
	json.NewEncoder(w).Encode(response)
}

func healthHandler(w http.ResponseWriter, r *http.Request) {
	w.WriteHeader(http.StatusOK)
	w.Write([]byte("ok"))
}

func main() {
	http.HandleFunc("/v1/apply", applyHandler)
	http.HandleFunc("/v1/plan", planHandler)
	http.HandleFunc("/health", healthHandler)
	log.Println("Terraform provider API listening on :8443")
	log.Fatal(http.ListenAndServe(":8443", nil))
}
